class Solution {
public:
    int missingNumber(std::vector<int>& arr) {
        int n = arr.size();
        int diff = (arr.back() - arr[0]) / n;
        for (int i = 0; i < n; ++i) {
            int expected = arr[0] + i * diff;
            if (arr[i] != expected) return expected;
        }
        return arr[0];
    }
};

class Solution {
    public int missingNumber(int[] arr) {
        int n = arr.length;
        int diff = (arr[n - 1] - arr[0]) / n;
        for (int i = 0; i < n; i++) {
            int expected = arr[0] + i * diff;
            if (arr[i] != expected) return expected;
        }
        return arr[0];
    }
}

var missingNumber = function(arr) {
    const n = arr.length;
    const diff = Math.trunc((arr[n - 1] - arr[0]) / n);
    for (let i = 0; i < n; i++) {
        const expected = arr[0] + i * diff;
        if (arr[i] !== expected) return expected;
    }
    return arr[0];
};
